	m.HandleFunc("GET "+options.BaseURL+"/vehicles/{id}", wrapper.GetVehicle)
	m.HandleFunc("GET "+options.BaseURL+"/vehicles/{id}/cover_photo", wrapper.GetVehicleCoverPhoto)
